import {jiraSite} from './jira-core.js';
export const noteKinds=['Observation','Bug candidate','Question','Coverage','Blocked','Automated check'];
export const blankWorkspace=()=>({version:1,sprint:{name:'Current iteration',goal:'',done:'Acceptance examples reviewed\nRelevant regression evidence reviewed\nRemaining risks discussed with the team',retro:''},stories:[],sessions:[]});
export function elapsed(session,now=Date.now()){return (session.elapsedMs||0)+(session.runningSince?Math.max(0,now-session.runningSince):0);}
export function changeStory(previous,values){const changed=['title','criteria','risks','examples','questions'].some(k=>previous[k]!==values[k]);return {...previous,...values,revision:(previous.revision||1)+(changed?1:0),status:changed&&previous.status==='Done'?'Review':values.status,reviewer:changed?'':values.reviewer,decision:changed?'':values.decision};}
export function validateWorkspace(value){
  if(value?.version!==1||!value.sprint||!Array.isArray(value.stories)||!Array.isArray(value.sessions)||value.stories.length>100||value.sessions.length>300)throw Error('Invalid workspace or capacity exceeded (100 stories / 300 sessions).');
  const str=(v,max=12000)=>{if(typeof v!=='string'||v.length>max)throw Error('Invalid or oversized text field.');return v;};
  const sprint=Object.fromEntries(['name','goal','done','retro'].map(k=>[k,str(value.sprint[k])]));const ids=new Set();
  const stories=value.stories.map(s=>{const id=str(s.id,100);if(ids.has(id))throw Error('Duplicate story ID.');ids.add(id);if(!['Planned','Testing','Review','Done'].includes(s.status)||!['High','Medium','Low'].includes(s.priority)||!Number.isInteger(s.revision)||s.revision<1)throw Error('Invalid story state.');let jira;if(s.jira){if(!/^[A-Z][A-Z0-9_]*-\d+$/i.test(s.jira.key))throw Error('Invalid Jira source key');jira={site:jiraSite(s.jira.site),key:str(s.jira.key,100),sprintId:str(s.jira.sprintId,30),updated:str(s.jira.updated,100),status:str(s.jira.status,200),type:str(s.jira.type,200)};}return {id,...(jira?{jira}:{}),revision:s.revision,status:s.status,priority:s.priority,...Object.fromEntries(['title','criteria','risks','examples','questions','reviewer','decision'].map(k=>[k,str(s[k]||'')]))};});
  const sessionIds=new Set();const sessions=value.sessions.map(s=>{if(!ids.has(s.storyId)||sessionIds.has(s.id))throw Error('Session has an invalid story or duplicate ID.');sessionIds.add(str(s.id,100));if(!['Ready','Running','Paused','Ended'].includes(s.state)||!Number.isFinite(s.elapsedMs)||s.elapsedMs<0||!Number.isFinite(s.timebox)||s.timebox<1||s.timebox>180||!Number.isInteger(s.revision)||s.revision<1||!Array.isArray(s.notes)||s.notes.length>500)throw Error('Invalid session.');return {id:s.id,storyId:s.storyId,revision:s.revision,state:s.state==='Running'?'Paused':s.state,runningSince:0,elapsedMs:s.elapsedMs,timebox:s.timebox,...Object.fromEntries(['charter','oracle','coverage','debrief','next'].map(k=>[k,str(s[k]||'')])),notes:s.notes.map(n=>{if(!noteKinds.includes(n.kind))throw Error('Invalid note type.');return{kind:n.kind,text:str(n.text),at:str(n.at,60)};})};});return {version:1,sprint,stories,sessions};
}
export function reportText(w){
  const out=[`# ${w.sprint.name}`,`Goal: ${w.sprint.goal||'Not recorded'}`,'\n## Team definition of done',w.sprint.done,'\n## Testing story'];
  for(const story of w.stories){out.push(`\n### ${story.title} · ${story.status} · ${story.priority} risk priority · revision ${story.revision}`,`Acceptance criteria: ${story.criteria}`,`Examples: ${story.examples}`,`Risks: ${story.risks}`,`Open questions: ${story.questions}`);for(const s of w.sessions.filter(s=>s.storyId===story.id)){out.push(`\nSession: ${s.charter}`,`Based on story revision ${s.revision}${s.revision!==story.revision?' (older than current story)':''} · ${s.state} · ${Math.round(elapsed(s)/60000)} minutes`, `Oracle / basis for judgment: ${s.oracle}`,`Intended coverage: ${s.coverage}`,...s.notes.map(n=>`- ${n.at} [${n.kind}] ${n.text}`),`Debrief: ${s.debrief||'Not recorded'}`,`Next investigation: ${s.next||'Not recorded'}`);}out.push(`Reviewer: ${story.reviewer||'Not recorded'}`,`Decision / remaining risks: ${story.decision||'Not recorded'}`);}
  out.push('\n## Retrospective',w.sprint.retro||'Not recorded','\nAutomated checks are supporting evidence, not complete testing or a release guarantee. Story states are human judgments.');return out.join('\n\n');
}
export function summarizeApi(run){if(!run||typeof run.name!=='string'||!Array.isArray(run.checks)||!Number.isInteger(run.status)||typeof run.source!=='string')throw Error('Invalid API evidence');return `API check: ${run.name.slice(0,200)} | ${run.source.slice(0,80)} | HTTP ${run.status} | ${run.checks.filter(c=>c.pass===true).length}/${run.checks.length} assertions passed | ${String(run.timestamp).slice(0,40)}. Request/response bodies, credentials and assertion values omitted. This covers only the checks executed.`;}
